<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fixifier Plus | Job Verification</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,Arial;color:#16243d;background:#f5f8fd}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer}header{background:#fff;border-bottom:1px solid #e1e8f4;position:sticky;top:0;z-index:5}.nav{max-width:1240px;margin:auto;padding:17px 24px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-weight:900;font-size:23px;color:#155eef}.brand span{color:#17243c}.pill{border-radius:100px;background:#eaf1ff;color:#155eef;padding:8px 13px;font-weight:700;font-size:12px}.wrap{max-width:1240px;margin:30px auto;padding:0 24px}.intro{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}.intro h1{font-size:clamp(26px,4vw,38px);margin:5px 0}.muted{color:#64748b}.layout{display:grid;grid-template-columns:245px 1fr;gap:22px;margin-top:24px}.card{background:white;border:1px solid #e2eaf5;border-radius:18px;padding:22px;box-shadow:0 8px 26px #1a3e7508}.sidebar{height:max-content}.sidebar button{display:block;width:100%;text-align:left;border:0;background:transparent;padding:13px;border-radius:10px;color:#465673;margin:4px 0}.sidebar button.active{background:#eaf1ff;color:#155eef;font-weight:800}.section{display:none}.section.active{display:block}.topline{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.tag{background:#fff3d8;color:#986000;border-radius:50px;padding:7px 11px;font-size:12px;font-weight:800}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.photo{min-height:225px;border-radius:14px;background:linear-gradient(145deg,#dbe8f9,#b5cce6);display:grid;place-items:center;text-align:center;overflow:hidden;color:#375478;position:relative}.photo.after{background:linear-gradient(145deg,#d7f4eb,#9fd6c3)}.photo svg{width:88px;height:88px;opacity:.6}.photo img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}.photo small{display:block}.photo .fallback{padding:15px}.photo-label{font-size:13px;font-weight:800;margin:0 0 10px}.btn{border:0;border-radius:10px;padding:12px 18px;font-weight:800;background:#155eef;color:#fff}.btn.secondary{background:#eaf1ff;color:#155eef}.btn.danger{background:#fff0ef;color:#bd3434}.btn:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.timeline{list-style:none;margin:0;padding:0}.timeline li{border-left:2px solid #d6e4fa;margin-left:7px;padding:0 0 23px 20px;position:relative}.timeline li:before{content:'';width:12px;height:12px;border-radius:50%;background:#155eef;position:absolute;left:-7px;top:4px}.timeline li:last-child{border:0}.timeline strong{display:block}.timeline small{color:#64748b}.statrow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#f3f7ff;border-radius:12px;padding:14px}.stat strong{display:block;font-size:22px;margin-top:6px}.field{display:grid;gap:7px;margin:15px 0}.field label{font-weight:700;font-size:14px}.field input,.field select,.field textarea{border:1px solid #ccd8e8;border-radius:10px;padding:12px;width:100%;background:#fff;color:#17243c}.field textarea{min-height:110px;resize:vertical}.notice{padding:13px 15px;border-radius:11px;background:#eef5ff;color:#35537b;font-size:14px;margin:16px 0}.success{background:#e6f8ef;color:#146444}.error{background:#fff0ef;color:#a33232}.hidden{display:none!important}.divider{border:0;border-top:1px solid #e8edf5;margin:20px 0}.modal-backdrop{position:fixed;inset:0;background:#0d1b35a8;display:grid;place-items:center;z-index:10;padding:18px}.modal{width:min(100%,510px);background:#fff;border-radius:18px;padding:25px;max-height:90vh;overflow:auto}.modal h2{margin-top:0}.foot{padding:25px;text-align:center;color:#75839a;font-size:12px}@media(max-width:780px){.layout{grid-template-columns:1fr}.sidebar{display:flex;overflow-x:auto;padding:8px}.sidebar button{white-space:nowrap}.grid{grid-template-columns:1fr}.statrow{grid-template-columns:1fr 1fr}.wrap{padding:0 14px}.card{padding:16px}}@media(max-width:430px){.statrow{grid-template-columns:1fr}.nav{padding:14px}.pill{font-size:10px}}
</style></head><body><header><div class="nav"><div class="brand">fixifier<span> plus</span></div><span class="pill">CUSTOMER PORTAL · DEMO</span></div></header><main class="wrap"><div class="intro"><div><div class="muted">Customer dashboard / Job verification</div><h1>Review your completed repair</h1><div class="muted">Compare evidence, approve work, or request support.</div></div><span class="pill" id="headerStatus">Awaiting your review</span></div><div class="layout"><aside class="card sidebar" aria-label="Dashboard sections"><button class="active" data-tab="review">📷 Job evidence</button><button data-tab="history">🕒 Job timeline</button><button data-tab="disputes">⚖️ Dispute center</button><button data-tab="payments">💳 Payment status</button></aside><div><section class="section active" id="review"><div class="card"><div class="topline"><div><div class="muted">JOB #FX-2026-0148</div><h2>Air conditioner repair</h2><div class="muted">Technician: Musa Ibrahim · Ikeja, Lagos</div></div><span class="tag" id="jobTag">Review required</span></div><hr class="divider"><div class="statrow"><div class="stat">Service charge<strong>₦18,500</strong></div><div class="stat">Evidence<strong>2 stages</strong></div><div class="stat">Job date<strong>21 Sep</strong></div></div><h3>Before & after evidence</h3><p class="muted">The technician submitted these records for your review. The illustrative placeholders below are not actual repair photographs.</p><div class="grid"><div><p class="photo-label">BEFORE · Initial condition</p><div class="photo" id="beforePhoto"><div class="fallback"><svg viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="3"><rect x="12" y="28" width="76" height="45" rx="6"/><path d="M22 42h56M22 51h56M22 60h56M38 21h24"/></svg><strong>Before repair</strong><small>Illustrative evidence placeholder</small></div></div><p class="muted">Reported issue: AC not cooling; blocked filter and drainage.</p></div><div><p class="photo-label">AFTER · Completed repair</p><div class="photo after" id="afterPhoto"><div class="fallback"><svg viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="3"><rect x="12" y="28" width="76" height="45" rx="6"/><path d="M22 42h56M22 51h56M22 60h56M38 21h24M40 84l7 7 15-17"/></svg><strong>After repair</strong><small>Illustrative evidence placeholder</small></div></div><p class="muted">Technician reports filter cleaning, drain clearing and cooling test.</p></div></div><div class="notice">Production requirement: use timestamped, job-linked photographs uploaded by the assigned technician. This demo does not verify image authenticity or connect to a technician account.</div><h3>Technician completion note</h3><p>“Cleaned the filter and drainage line, checked the fan and tested cooling. Please confirm the AC is functioning as expected.”</p><div class="actions" id="reviewActions"><button class="btn" id="approveBtn">Approve completed work</button><button class="btn danger" id="disputeBtn">Raise a dispute</button></div><div class="notice hidden" id="resultMessage" role="status"></div></div></section><section class="section" id="history"><div class="card"><h2>Job timeline</h2><p class="muted">Illustrative history of this service request.</p><ol class="timeline" id="timeline"><li><strong>Service requested</strong><small>21 Sep 2026 · 09:00</small></li><li><strong>Quotation accepted</strong><small>21 Sep 2026 · 09:45</small></li><li><strong>Before photos submitted</strong><small>21 Sep 2026 · 10:30</small></li><li><strong>Technician marked repair complete</strong><small>21 Sep 2026 · 13:20</small></li><li><strong>After photos submitted</strong><small>21 Sep 2026 · 13:25</small></li></ol></div></section><section class="section" id="disputes"><div class="card"><h2>Dispute center</h2><p class="muted">If the repair is incomplete or evidence does not match the work, submit a case for review.</p><div id="disputeEmpty" class="notice">No dispute has been submitted for this job.</div><div id="disputeDetails" class="hidden"></div><button class="btn danger" id="disputePageBtn">Open dispute form</button></div></section><section class="section" id="payments"><div class="card"><h2>Payment status</h2><div class="statrow"><div class="stat">Service total<strong>₦18,500</strong></div><div class="stat">Payment mode<strong style="font-size:16px">Demo hold</strong></div><div class="stat">Settlement<strong style="font-size:16px" id="settlement">Pending</strong></div></div><div class="notice" id="paymentNotice">Payment is represented by a simulated hold. No money is collected, held or transferred by this prototype.</div><p class="muted">In production, settlement requires payment-provider confirmation, platform rules, and appropriate dispute handling.</p></div></section></div></div></main><div class="modal-backdrop hidden" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><h2 id="modalTitle">Confirm action</h2><div id="approveContent" class="hidden"><p>Confirm that the repair is satisfactory and you have reviewed the submitted evidence.</p><div class="notice">This is a demo confirmation. It does not transfer funds.</div><div class="actions"><button class="btn" id="confirmApprove">Confirm approval</button><button class="btn secondary" data-close>Cancel</button></div></div><form id="disputeForm" class="hidden"><p class="muted">Describe the issue so Fixifier support can review it.</p><div class="field"><label for="reason">Reason</label><select id="reason" required><option value="">Select a reason</option><option>Repair incomplete</option><option>Issue persists</option><option>Photos do not match the work</option><option>Property damage</option><option>Other concern</option></select></div><div class="field"><label for="details">Description</label><textarea id="details" required minlength="15" placeholder="Explain what happened (at least 15 characters)"></textarea></div><div class="field"><label for="supportPhoto">Supporting photo (optional)</label><input type="file" id="supportPhoto" accept="image/*"><small class="muted">Preview only; files are not uploaded to a server.</small><div id="supportPreview"></div></div><div class="actions"><button class="btn danger" type="submit">Submit dispute</button><button class="btn secondary" type="button" data-close>Cancel</button></div></form></div></div><footer class="foot">Fixifier Plus · Interactive prototype · Sample data only</footer><script>
(()=>{'use strict';const KEY='fixifier_plus_verification_v1';const $=id=>document.getElementById(id);let state={status:'review',dispute:null};try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored&&['review','approved','disputed'].includes(stored.status))state=stored}catch(e){}const save=()=>localStorage.setItem(KEY,JSON.stringify(state));function showTab(id){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));document.querySelectorAll('.section').forEach(s=>s.classList.toggle('active',s.id===id))}document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));function modal(type){$('modal').classList.remove('hidden');$('approveContent').classList.toggle('hidden',type!=='approve');$('disputeForm').classList.toggle('hidden',type!=='dispute');$('modalTitle').textContent=type==='approve'?'Approve completed work':'Raise a dispute'}function close(){$('modal').classList.add('hidden')}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});$('approveBtn').onclick=()=>modal('approve');$('disputeBtn').onclick=()=>modal('dispute');$('disputePageBtn').onclick=()=>modal('dispute');$('confirmApprove').onclick=()=>{if(state.status!=='review')return;state.status='approved';save();close();render()};$('supportPhoto').addEventListener('change',e=>{const file=e.target.files[0],el=$('supportPreview');el.replaceChildren();if(file){const img=document.createElement('img');img.style.cssText='max-width:100%;max-height:140px;border-radius:10px;margin-top:10px';const url=URL.createObjectURL(file);img.onload=()=>URL.revokeObjectURL(url);img.src=url;img.alt='Supporting evidence preview';el.append(img)}});$('disputeForm').addEventListener('submit',e=>{e.preventDefault();if(state.status!=='review')return;state.status='disputed';state.dispute={reason:$('reason').value,details:$('details').value,reference:'DSP-0148'};save();close();render();showTab('disputes')});function render(){const approved=state.status==='approved',disputed=state.status==='disputed';$('headerStatus').textContent=approved?'Work approved':disputed?'Dispute under review':'Awaiting your review';$('jobTag').textContent=approved?'Customer approved':disputed?'Dispute submitted':'Review required';$('reviewActions').classList.toggle('hidden',approved||disputed);$('resultMessage').classList.toggle('hidden',!(approved||disputed));$('resultMessage').className='notice '+(approved?'success':disputed?'error':'hidden');$('resultMessage').textContent=approved?'You approved the completed repair. This demo has updated the payment status; no funds were transferred.':disputed?'Your dispute was recorded locally. In production, Fixifier support would review the case before settlement.':'';$('settlement').textContent=approved?'Eligible':disputed?'On hold':'Pending';$('paymentNotice').textContent=approved?'Approval recorded. Simulated settlement is eligible; no actual payment was made.':disputed?'Dispute submitted. Simulated settlement remains on hold.':'Payment is represented by a simulated hold. No money is collected, held or transferred by this prototype.';$('disputeEmpty').classList.toggle('hidden',disputed);$('disputeDetails').classList.toggle('hidden',!disputed);$('disputePageBtn').classList.toggle('hidden',approved||disputed);$('disputeDetails').replaceChildren();if(disputed&&state.dispute){const h=document.createElement('h3');h.textContent='Case '+state.dispute.reference;const p=document.createElement('p');p.textContent=state.dispute.reason+' — '+state.dispute.details;const n=document.createElement('div');n.className='notice';n.textContent='Status: awaiting support review (simulation).';$('disputeDetails').append(h,p,n)}document.querySelectorAll('.dynamic-timeline').forEach(n=>n.remove());if(approved||disputed){const li=document.createElement('li');li.className='dynamic-timeline';const strong=document.createElement('strong');strong.textContent=approved?'Customer approved work':'Customer submitted dispute';const small=document.createElement('small');small.textContent='Recorded in this browser';li.append(strong,small);$('timeline').append(li)}}render()})();
</script></body></html>
